@extends('admin.layout') @section('content')<h1 class="h3 mb-3">{{ $gallery ? 'Edit' : 'Add' }} Gallery</h1><form method="post" action="{{ $gallery ? route('admin.resource.update',['resource'=>'gallery','id'=>$gallery->id]) : route('admin.resource.store','gallery') }}">@csrf @if($gallery)@method('put')@endif<div class="mb-3"><label class="form-label">Gallery Title</label><input required name="title" class="form-control" value="{{old('title',$gallery->title ?? '')}}"></div><div class="mb-3"><label class="form-label">Date</label><input required type="date" name="date" class="form-control" value="{{old('date',$gallery->date ?? '')}}"></div><h4>Images</h4><table class="table table-bordered" id="gallery-images"><thead><tr><th>Image Path</th><th>Sort Order</th><th></th></tr></thead><tbody>@foreach($images as $image)<tr><td><input name="gallery_image[{{$loop->index}}][image]" class="form-control" value="{{$image->image}}"></td><td><input name="gallery_image[{{$loop->index}}][sort_order]" class="form-control" value="{{$image->sort}}"></td><td><button type="button" class="btn btn-outline-danger remove">Remove</button></td></tr>@endforeach</tbody><tfoot><tr><td colspan="3"><button type="button" class="btn btn-outline-primary" id="add-gallery-image">Add Image</button></td></tr></tfoot></table><button class="btn btn-success">Save</button> <a class="btn btn-outline-secondary" href="{{route('admin.resource.index','gallery')}}">Cancel</a></form>@push('scripts')<script>(function(){var table=document.getElementById('gallery-images');function bind(){table.querySelectorAll('.remove').forEach(function(b){b.onclick=function(){b.closest('tr').remove()}})}bind();document.getElementById('add-gallery-image').onclick=function(){var i=table.querySelectorAll('tbody tr').length;table.querySelector('tbody').insertAdjacentHTML('beforeend','<tr><td><input name="gallery_image['+i+'][image]" class="form-control"></td><td><input name="gallery_image['+i+'][sort_order]" class="form-control"></td><td><b